const ar=v=>String(v).replace(/[0-9]/g,d=>AR[d]),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),fmt=n=>ar(Number(n.toFixed(1))),pct=n=>fmt(n)+'٪',id=()=>globalThis.crypto?.randomUUID?.()||Date.now().toString(36)+Math.random().toString(36).slice(2),date=s=>new Date(s).toLocaleDateString('ar-SA',{calendar:'gregory',year:'numeric',month:'short',day:'numeric'});
const paths={home:'<rect x="3" y="3" width="7" height="7" rx="2"/><rect x="14" y="3" width="7" height="7" rx="2"/><rect x="3" y="14" width="7" height="7" rx="2"/><rect x="14" y="14" width="7" height="7" rx="2"/>',exam:'<rect x="5" y="4" width="14" height="17" rx="2"/><path d="M9 3h6v4H9zM9 12h6M9 16h4"/>',scan:'<path d="M8 3H4a1 1 0 0 0-1 1v4m13-5h4a1 1 0 0 1 1 1v4M3 16v4a1 1 0 0 0 1 1h4m13-5v4a1 1 0 0 1-1 1h-4M2 12h20"/><path d="M8 7h8v10H8z"/>',chart:'<path d="M4 3v18h17M8 17v-5m5 5V7m5 10V4"/>',users:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3m1-16a3 3 0 0 1 0 6m3 10v-3a6 6 0 0 0-3-5"/>',settings:'<path d="M4 6h16M4 12h16M4 18h16"/><circle cx="8" cy="6" r="2" fill="currentColor"/><circle cx="16" cy="12" r="2" fill="currentColor"/><circle cx="10" cy="18" r="2" fill="currentColor"/>',guide:'<path d="M12 5C7 2 4 3 2 4v16c4-2 7-1 10 1 3-2 6-3 10-1V4c-3-2-6-2-10 1Zm0 0v16"/>',plus:'<path d="M12 5v14M5 12h14"/>',arrow:'<path d="m14 6-6 6 6 6M8 12h12"/>',check:'<path d="m5 12 4 4L19 6"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 16v5h16v-5"/>',print:'<path d="M7 8V3h10v5M7 17H3v-7a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2v7h-4M7 14h10v8H7z"/>',edit:'<path d="m16 3 5 5-12 12-6 1 1-6ZM13 6l5 5"/>',trash:'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7"/>',copy:'<rect x="8" y="8" width="13" height="13" rx="2"/><path d="M16 8V3H3v13h5"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',camera:'<path d="M3 7h5l2-3h4l2 3h5v14H3z"/><circle cx="12" cy="14" r="4"/>',image:'<rect x="3" y="3" width="18" height="18" rx="2"/><circle cx="8" cy="8" r="2"/><path d="m3 18 6-6 4 3 3-4 5 6"/>',moon:'<path d="M21 13a9 9 0 0 1-10-10 9 9 0 1 0 10 10Z"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 1v2m0 18v2M1 12h2m18 0h2M4 4l2 2m12 12 2 2M4 20l2-2M18 6l2-2"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v1"/>',rotate:'<path d="M20 8a8 8 0 1 0 0 8M20 3v5h-5"/>',spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5ZM20 2v4m-2-2h4"/>',shield:'<path d="m12 2 9 4v6c0 5-9 10-9 10S3 17 3 12V6z"/><path d="m8 12 3 3 5-6"/>',target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',file:'<path d="M14 2H5v20h14V7ZM14 2v6h5M8 12h8m-8 4h8"/>'};
const icon=(n,extra='')=>`<svg ${extra} width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[n]||paths.file}</svg>`;
const KEY='basirah.v1:'+new URL('.',location.href).pathname,navs=[['home','نظرة عامة','home'],['exams','الاختبارات','exam'],['scan','التصحيح','scan'],['results','النتائج والتحليل','chart'],['settings','الإعدادات','settings'],['guide','دليل الاستخدام','guide']];
let db={version:1,quizzes:[],results:[],roster:[],theme:'light'},storageError=false,loadError=false;
try{const raw=localStorage.getItem(KEY);if(raw)db=validateDB(JSON.parse(raw));}catch(e){loadError=true;}
let route='home',draft=null,selectedQuiz='',reportQuiz='',search='',scan={quizId:'',canvas:null,corners:null,manual:false,points:[],answers:null,readings:null,reviewed:[],confirmed:false,demo:false,name:'',studentId:'',queue:[],queueTotal:0},cameraStream=null,toastTimer,lastSavedResultId='';
const sample={id:'demo',title:'تجربة بصيرة · المهارات الرياضية',className:'ورقة تدريبية',options:4,created:new Date().toISOString(),questions:Array.from({length:10},(_,i)=>({answer:[0,2,1,3,0,1,2,3,1,0][i],skill:i<4?'الضرب':i<7?'القسمة':'القياس',weight:1}))};
function save(){if(loadError)throw Error('تعذّر قراءة البيانات السابقة. صدّري نسخة الاستعادة من الإعدادات قبل البدء.');try{localStorage.setItem(KEY,JSON.stringify(db));storageError=false;}catch(e){storageError=true;throw Error('تعذّر الحفظ في المتصفح. صدّري نسخة احتياطية، وتحققي من مساحة الجهاز وإعدادات المتصفح.');}}
function quizById(qid){return qid==='demo'?sample:db.quizzes.find(q=>q.id===qid);}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),5000);}
function modal(title,body,actions=''){stopCamera();$('#modal-content').innerHTML=`<div class="modal-head"><h2>${esc(title)}</h2><button class="icon-btn" data-action="close-modal" aria-label="إغلاق">${icon('close')}</button></div>${body}${actions?`<div class="row" style="margin-top:20px">${actions}</div>`:''}`;$('#modal').showModal();}
function closeModal(){stopCamera();$('#modal').close();}
function stopCamera(){cameraStream?.getTracks().forEach(t=>t.stop());cameraStream=null;}
function confirmAction(title,text,fn,label='تأكيد'){modal(title,`<p>${esc(text)}</p>`,`<button class="btn primary" id="confirm-action">${esc(label)}</button><button class="btn" data-action="close-modal">إلغاء</button>`);$('#confirm-action').onclick=async()=>{closeModal();try{await fn();}catch(e){toast(e.message);}};}
function download(name,content,type){const url=URL.createObjectURL(content instanceof Blob?content:new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.hidden=true;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);}
function go(r){if(location.hash==='#'+r)render();else location.hash=r;}
function header(title,subtitle,actions=''){return `<div class="page-head"><div><h1>${title}</h1><p>${subtitle}</p></div><div class="row">${actions}</div></div>`;}
function stats(items){return `<div class="stats">${items.map(([n,label,value])=>`<div class="stat"><div class="stat-icon">${icon(n)}</div><div><b>${value}</b><small>${label}</small></div></div>`).join('')}</div>`;}
function notice(text,color=''){return `<div class="notice ${color}">${icon('info')}<div>${text}</div></div>`;}
function empty(title,text,button=''){return `<div class="empty">${icon('file')}<h3>${title}</h3><p>${text}</p>${button}</div>`;}
function quizOptions(value,includeDemo=false){return (includeDemo&&value==='demo'?`<option value="demo" selected>${esc(sample.title)}</option>`:'')+`<option value="">اختر الاختبار</option>`+db.quizzes.map(q=>`<option value="${esc(q.id)}" ${q.id===value?'selected':''}>${esc(q.title)}${q.className?' · '+esc(q.className):''}</option>`).join('');}
function render(){route=location.hash.slice(1)||'home';if(!navs.some(n=>n[0]===route)&&route!=='editor')route='home';$('#navigation').innerHTML=navs.map(([key,label,ic])=>`<button class="nav-link ${route===key||(route==='editor'&&key==='exams')?'active':''}" data-nav="${key}" ${route===key?'aria-current="page"':''}>${icon(ic)}<span>${label}</span></button>`).join('');$('#crumb').textContent=navs.find(n=>n[0]===route)?.[1]||'إعداد الاختبار';document.documentElement.dataset.theme=db.theme;$('#theme').innerHTML=icon(db.theme==='dark'?'sun':'moon');
  const pages={home:homePage,exams:examsPage,editor:editorPage,scan:scanPage,results:resultsPage,settings:settingsPage,guide:guidePage};$('#main').innerHTML=pages[route]();
  if(loadError)$('#main').insertAdjacentHTML('afterbegin',notice('لم نستطع قراءة البيانات المحفوظة. لم تُحذف. افتح الإعدادات لتنزيل نسخة استعادة.'));
  if(route==='scan')bindScanner();
}
function homePage(){
  const grades=db.results.map(r=>{const q=quizById(r.quizId);return q?O.grade(q,r.answers).percent:0;}),mean=grades.length?grades.reduce((a,b)=>a+b,0)/grades.length:0;
  return header('كل إجابة تحكي شيئًا.','اقرأ ما وراء الدرجة، واجعل التقييم بداية التعلّم.',`<button class="btn primary" data-action="new-exam">${icon('plus')}اختبار جديد</button>`)+
  `<section class="hero"><div><div class="kicker">رؤية أوضح · تعلّم أفضل</div><h2>صحّح بثقة.<br>وافهم النتائج بعمق.</h2><p>من ورقة مظلّلة إلى صورة واضحة عن التعلّم.<br>تصحيح، وتحليل، وخطوة تالية لكل مهارة.</p><div class="row"><button class="btn primary" data-nav="scan">${icon('scan')}ابدأ التصحيح</button><button class="btn ghost" data-action="demo">${icon('spark')}جرّب بورقة تدريبية</button></div></div><div class="hero-art" aria-hidden="true"><div class="paper-mini"><div class="paper-line short"></div><div class="paper-line"></div>${Array.from({length:5},(_,i)=>`<div class="bubbles-mini">${Array.from({length:4},(_,j)=>`<i class="${j===i%4?'on':''}"></i>`).join('')}</div>`).join('')}</div><div class="floating-check">${icon('check')}</div><div class="scanline"></div><div class="scan-label">من التظليل… إلى التحليل</div></div></section>`+
  stats([['exam','اختباراتك',ar(db.quizzes.length)],['scan','أوراق معتمدة',ar(db.results.length)],['chart','متوسط النتائج',grades.length?pct(mean):'—'],['users','طلبة في القائمة',ar(db.roster.length)]])+
  `<div class="grid-two"><div><section class="panel"><div class="panel-head"><h2>ثلاث خطوات لرؤية أوضح</h2><span class="badge">ابدأ هنا</span></div><div class="workflow"><div><span class="step-num">١</span><h3>أعدّ الاختبار</h3><p>حدّد المفتاح والمهارات،<br>واطبع نموذج الإجابة.</p></div><div><span class="step-num">٢</span><h3>امسح وراجع</h3><p>ارفع صورة الورقة،<br>وراجع الإجابات الملتبسة.</p></div><div><span class="step-num">٣</span><h3>حلّل وطوّر</h3><p>اكتشف جوانب الإتقان،<br>وحدّد أولوية التدريب.</p></div></div></section><section class="panel"><div class="panel-head"><h2>آخر اختباراتك</h2><button class="btn link" data-nav="exams">عرض الكل ${icon('arrow')}</button></div>${db.quizzes.length?db.quizzes.slice(-3).reverse().map(q=>`<div class="report-line"><div><b>${esc(q.title)}</b><small class="muted" style="display:block">${ar(q.questions.length)} سؤال · ${esc(q.className||'بدون فصل')}</small></div><button class="btn small" data-action="scan-exam" data-id="${esc(q.id)}">تصحيح ${icon('scan')}</button></div>`).join(''):empty('رحلتك تبدأ باختبار','أنشئ مفتاح الإجابة الأول، ثم اطبع النموذج وابدأ.',`<button class="btn soft small" data-action="new-exam">${icon('plus')}إنشاء اختبار</button>`)}</section></div><div><section class="panel"><div class="panel-head"><div><h2>نافذة على التعلّم</h2><p>التحليل يبدأ بالنتائج المعتمدة</p></div>${icon('chart')}</div>${db.results.length?`<div class="distribution">${[[90,101,'٩٠٪ فأكثر'],[75,90,'٧٥–٨٩٪'],[50,75,'٥٠–٧٤٪'],[0,50,'أقل من ٥٠٪']].map(([a,b,t])=>`<div><b>${ar(grades.filter(g=>g>=a&&g<b).length)}</b><small>${t}</small></div>`).join('')}</div><button class="btn link" style="margin-top:20px" data-nav="results">استكشف النتائج ${icon('arrow')}</button>`:`<div class="chart-empty" aria-hidden="true"><i style="height:40%"></i><i style="height:65%"></i><i style="height:50%"></i><i style="height:82%"></i><i style="height:60%"></i><span>بانتظار أول ورقة معتمدة</span></div><p class="skeleton-note">ستظهر هنا نتائجك الفعلية بعد التصحيح.</p>`}</section><section class="panel" style="background:var(--soft);border-color:transparent"><div class="row" style="color:var(--teal)">${icon('shield')}<h3>مساحتك، على جهازك</h3></div><p style="font-size:11px;color:var(--muted);margin-top:10px">لا تُرسل صور الأوراق أو أسماء الطلبة إلى خادم. احتفظ بنسخة احتياطية لنقل عملك إلى جهاز آخر.</p><button class="btn link" style="margin-top:12px;font-size:11px" data-action="backup">تنزيل نسخة احتياطية ${icon('download')}</button></section></div></div>`;
}
function examsPage(){return header('اختباراتك','مفتاح واضح، ونموذج مناسب، ونتائج يمكن البناء عليها.',`<button class="btn primary" data-action="new-exam">${icon('plus')}اختبار جديد</button>`)+
  `<div class="row between" style="margin-bottom:20px"><span class="muted" style="font-size:12px">${ar(db.quizzes.length)} اختبار في مساحتك</span><button class="btn small" data-action="import">${icon('upload')}استيراد اختبار أو نسخة</button></div>`+
  (db.quizzes.length?`<div class="exam-grid">${db.quizzes.slice().reverse().map(q=>{const count=db.results.filter(r=>r.quizId===q.id).length;return `<article class="exam-card"><div class="exam-icon">${icon('exam')}</div><span class="badge card-status ${count?'':'gold'}">${count?ar(count)+' ورقة':'جاهز للتصحيح'}</span><h3>${esc(q.title)}</h3><p>${esc(q.className||'جميع الفصول')} · ${date(q.created)}</p><div class="exam-meta"><span>${ar(q.questions.length)} سؤال</span><span>${ar(q.options)} خيارات</span><span>${ar(q.questions.reduce((s,x)=>s+x.weight,0))} درجة</span></div><div class="row"><button class="btn primary small" data-action="scan-exam" data-id="${esc(q.id)}">${icon('scan')}تصحيح</button><button class="btn small" data-action="sheet" data-id="${esc(q.id)}">${icon('print')}النموذج</button><button class="icon-btn" aria-label="تحليل ${esc(q.title)}" title="التحليل" data-action="report-exam" data-id="${esc(q.id)}">${icon('chart')}</button><button class="icon-btn" aria-label="خيارات ${esc(q.title)}" title="خيارات الاختبار" data-action="exam-menu" data-id="${esc(q.id)}">${icon('settings')}</button></div></article>`;}).join('')}</div>`:`<section class="panel">${empty('لم تُنشئ اختبارًا بعد','يمكنك إعداد اختبار من سؤال واحد حتى ١٠٠ سؤال، بخيارات من اثنين إلى خمسة.',`<button class="btn primary" data-action="new-exam">${icon('plus')}أنشئ أول اختبار</button>`)}</section>`);}
function newDraft(original){draft=original?JSON.parse(JSON.stringify(original)):{id:id(),title:'',className:'',options:4,created:new Date().toISOString(),questions:Array.from({length:10},()=>({answer:null,skill:'',weight:1}))};go('editor');}
function editorPage(){if(!draft)return header('إعداد اختبار','ابدأ بإنشاء مفتاح للإجابات الصحيحة.')+empty('اختبار جديد','',`<button class="btn primary" data-action="new-exam">إنشاء</button>`);
  return header('إعداد الاختبار','حدد الإجابة الصحيحة لكل سؤال. إضافة المهارات تجعل التحليل أكثر فائدة.',`<button class="btn" data-nav="exams">العودة للاختبارات</button>`)+
  `<section class="panel"><div class="panel-head"><h2>بيانات الاختبار</h2><span class="badge">الخطوة ١</span></div><div class="form-grid"><label class="field"><span>عنوان الاختبار *</span><input id="quiz-title" maxlength="100" placeholder="مثال: الاختبار التشخيصي في الرياضيات" value="${esc(draft.title)}"></label><label class="field"><span>الصف أو الفصل</span><input id="quiz-class" maxlength="60" placeholder="مثال: ثالث ابتدائي — أ" value="${esc(draft.className)}"></label><label class="field"><span>عدد الأسئلة</span><input id="quiz-count" type="number" min="1" max="100" value="${draft.questions.length}"><small>من ١ إلى ١٠٠ سؤال في ورقة واحدة.</small></label><label class="field"><span>عدد الخيارات لكل سؤال</span><select id="quiz-options">${[2,3,4,5].map(n=>`<option value="${n}" ${n===draft.options?'selected':''}>${ar(n)} خيارات · ${letters.slice(0,n).join(' / ')}</option>`).join('')}</select></label></div></section>
  <section class="panel"><div class="panel-head"><div><h2>مفتاح الإجابة والمهارات</h2><p>لكل سؤال: الإجابة الصحيحة، والمهارة اختياريًا، ثم وزن السؤال.</p></div><span class="badge">الخطوة ٢</span></div><div class="key-rows">${draft.questions.map((q,i)=>`<div class="key-row"><span class="key-num">${ar(i+1)}</span><div class="key-choices">${letters.slice(0,draft.options).map((l,j)=>`<button class="bubble-btn ${q.answer===j?'on':''}" data-action="key" data-q="${i}" data-a="${j}" aria-label="السؤال ${ar(i+1)}، ${l}" aria-pressed="${q.answer===j}">${l}</button>`).join('')}</div><input class="skill-input" data-skill="${i}" aria-label="مهارة السؤال ${ar(i+1)}" placeholder="المهارة" maxlength="60" list="skills" value="${esc(q.skill)}"><input class="weight-input" data-weight="${i}" aria-label="درجة السؤال ${ar(i+1)}" title="وزن السؤال" type="number" min="0.5" max="100" step="0.5" value="${q.weight}"></div>`).join('')}</div><datalist id="skills">${['القيمة المنزلية','الجمع','الطرح','الضرب','القسمة','القياس','الأشكال الهندسية','عرض البيانات','الكسور','الاستدلال'].map(s=>`<option value="${s}">`).join('')}</datalist></section><div class="sticky-actions row between"><span class="muted" id="key-progress">${ar(draft.questions.filter(q=>q.answer!==null).length)} من ${ar(draft.questions.length)} إجابة محددة</span><button class="btn primary" data-action="save-exam">${icon('check')}حفظ الاختبار</button></div>`;
}
function captureDraft(){if(!draft)return;draft.title=$('#quiz-title')?.value.trim()||draft.title;draft.className=$('#quiz-class')?.value.trim()??draft.className;}
function scanPage(){const q=quizById(scan.quizId);return header('التصحيح البصري','صورة واضحة، مراجعة دقيقة، ثم اعتماد النتيجة.',`<button class="btn small" data-action="demo">${icon('spark')}تجربة جاهزة</button>`)+
  (scan.demo?'<div class="demo-ribbon">هذه ورقة تدريبية مصطنعة. لا تُضاف نتائجها إلى تقاريرك.</div>':'')+
  `<div class="scan-steps"><span class="active"><b>١</b>الاختبار والورقة</span><span class="${scan.canvas?'active':''}"><b>٢</b>مراجعة القراءة</span><span class="${scan.answers?'active':''}"><b>٣</b>اعتماد النتيجة</span></div><section class="panel"><div class="form-grid"><label class="field"><span>الاختبار</span><select id="scan-quiz">${quizOptions(scan.quizId,true)}</select></label><div class="field"><span>نموذج الإجابة</span><div class="row"><button class="btn" data-action="sheet" data-id="${q?esc(q.id):''}" ${q?'':'disabled'}>${icon('print')}عرض وطباعة النموذج</button><span class="muted" style="font-size:10px">استخدم نموذج بصيرة لهذا الاختبار.</span></div></div></div>${!db.quizzes.length&&!scan.demo?notice('ابدأ بإنشاء اختبار ومفتاح إجابة، أو جرّب الورقة التدريبية. <button class="btn link" data-action="new-exam">إنشاء اختبار</button>'):''}</section>
  <div class="scan-grid"><div><section class="panel"><div class="panel-head"><h2>${scan.canvas?'الورقة المرفوعة':'أضف ورقة الإجابة'}</h2>${scan.queue.length?`<span class="badge">${ar(scan.queue.length)} ورقة في الانتظار</span>`:'<span class="badge">معالجة على جهازك</span>'}</div>
  ${scan.canvas?`<div class="scan-image"><canvas id="scan-canvas" aria-label="صورة ورقة الإجابة؛ انقر مراكز المربعات عند الضبط اليدوي"></canvas></div><div id="alignment-message">${scan.error?notice(esc(scan.error)):scan.manual?notice('حدد مراكز المربعات بالترتيب: أعلى اليسار ← أعلى اليمين ← أسفل اليمين ← أسفل اليسار.'):scan.corners?notice('تم ضبط المربعات. تأكد أن العلامات الخضراء تقع على مراكزها، وأن الاختبار المختار يطابق الورقة.','teal'):notice('لم نتعرف على المربعات تلقائيًا. استخدم «ضبط المربعات» أو ارفع صورة أوضح.')}</div><div class="scan-toolbar row"><button class="btn small" data-action="manual-corners">${icon('target')}ضبط المربعات</button><button class="btn small" data-action="rotate">${icon('rotate')}تدوير</button><button class="btn small" data-action="choose-images">${icon('image')}صورة أخرى</button><button class="btn small" data-action="clear-scan">${icon('close')}إلغاء</button></div>`:
  `<div class="dropzone" id="dropzone"><div class="drop-icon">${icon('scan')}</div><h3>الورقة هنا، والنتيجة أقرب</h3><p>اسحب صور الأوراق أو اخترها من جهازك.<br>صوّر الصفحة كاملة، مع المربعات الأربعة.</p><div class="row"><button class="btn primary" data-action="choose-images" ${q?'':'disabled'}>${icon('upload')}رفع صور</button><button class="btn" data-action="camera" ${q?'':'disabled'}>${icon('camera')}الكاميرا</button></div><small>JPG · PNG · WEBP — حتى ٢٠ ميجابايت للصورة</small></div>`}
  <p class="muted" style="font-size:11px;margin-top:14px">${icon('info','style="width:13px;height:13px;vertical-align:middle"')} ضوء متجانس، ورقة مستوية، وتظليل كامل داخل الدائرة. امسح علامات الإجابة القديمة جيدًا.</p></section></div>
  <div><section class="panel"><div class="panel-head"><h2>مراجعة الإجابات</h2><span class="badge ${scan.readings?.some(r=>r.status!=='clear')?'gold':''}">${scan.readings?ar(scan.readings.filter((r,i)=>r.status!=='clear'&&!scan.reviewed[i]).length)+' للمراجعة':'بانتظار الصورة'}</span></div>${reviewHTML(q)}</section></div></div>`;
}
function reviewHTML(q){if(!scan.answers||!q)return empty('قبل اعتماد الدرجة','ستظهر هنا الإجابات المقروءة. تستطيع تعديل أي اختيار، ويجب مراجعة الخانات الفارغة أو الملتبسة.');const g=O.grade(q,scan.answers),pending=scan.readings.filter((r,i)=>r.status!=='clear'&&!scan.reviewed[i]).length;
 return `<div class="form-grid" style="gap:10px;margin-bottom:15px"><label class="field"><span>اسم الطالب/ـة</span><input id="scan-name" placeholder="الاسم أو رمز مستعار" maxlength="100" value="${esc(scan.name)}" list="roster-names" ${scan.demo?'disabled':''}></label><label class="field"><span>الرقم أو الرمز</span><input id="scan-student" placeholder="اختياري" maxlength="40" value="${esc(scan.studentId)}" ${scan.demo?'disabled':''}></label></div><datalist id="roster-names">${db.roster.map(r=>`<option value="${esc(r.name)}">${esc(r.code)}</option>`).join('')}</datalist><div class="review-list">${scan.answers.map((a,i)=>{const reading=scan.readings[i],reviewed=scan.reviewed[i],flag=reading.status!=='clear',label={clear:'قراءة واضحة',blank:'بلا إجابة',multiple:'تظليل متعدد',uncertain:'تظليل غير واضح'}[reading.status];return `<div class="review-row ${flag?'flagged':''} ${reviewed?'reviewed':''}" id="review-${i}"><div class="top"><span>السؤال ${ar(i+1)}</span><span class="badge ${flag&&!reviewed?'gold':''}">${reviewed?'تمت المراجعة':label}</span></div><div class="key-choices">${letters.slice(0,q.options).map((l,j)=>`<button class="bubble-btn ${a===j?'on':''}" data-action="review-answer" data-q="${i}" data-a="${j}" aria-pressed="${a===j}" aria-label="السؤال ${ar(i+1)}، ${l}">${l}</button>`).join('')}<button class="bubble-btn blank-btn ${a===null?'on':''}" data-action="review-answer" data-q="${i}" data-a="blank" aria-label="السؤال ${ar(i+1)}، بلا إجابة">فارغ</button>${flag&&!reviewed?`<button class="btn link check-flag" data-action="confirm-answer" data-q="${i}" title="تأكيد الاختيار الحالي">${icon('check')}تأكيد</button>`:''}</div></div>`;}).join('')}</div><div class="score-preview"><strong>${fmt(g.score)} من ${fmt(g.total)}</strong><div><b style="font-size:11px">درجة أولية · ${pct(g.percent)}</b><small style="display:block">${pending?ar(pending)+' إجابة تحتاج إلى مراجعة':'جاهزة للمراجعة النهائية'}</small></div></div>${scan.demo?notice('للتجربة فقط. غيّر الاختبار أو أنشئ اختبارًا لبدء تصحيح أوراقك.','teal'):`<div id="save-feedback" class="error-text" role="alert" hidden></div><p class="save-help">${pending?'ستظهر الأسئلة المعلَّمة في نافذة التأكيد قبل الحفظ.':'راجع الاسم والاختيارات، ثم أكّد حفظ النتيجة.'}</p><button class="btn primary save-result-btn" data-action="save-result">${icon('check')}اعتماد وحفظ النتيجة</button>`}`;
}
function updateReview(){const panel=$('#main .scan-grid>div:nth-child(2) .panel');if(!panel)return;const scroll=$('.review-list')?.scrollTop||0;const pending=scan.readings?.filter((r,i)=>r.status!=='clear'&&!scan.reviewed[i]).length||0;panel.innerHTML=`<div class="panel-head"><h2>مراجعة الإجابات</h2><span class="badge ${pending?'gold':''}">${ar(pending)} للمراجعة</span></div>${reviewHTML(quizById(scan.quizId))}`;if($('.review-list'))$('.review-list').scrollTop=scroll;}
function resultsPage(){if(!db.quizzes.some(q=>q.id===reportQuiz))reportQuiz=db.quizzes[0]?.id||'';const q=quizById(reportQuiz),results=db.results.filter(r=>r.quizId===reportQuiz),analysis=q?O.aggregate(q,results):null;
 return header('النتائج والتحليل','تتبّع الإتقان، واكتشف الأسئلة والمهارات التي تحتاج إلى دعم.',`<button class="btn" data-action="export-excel" ${results.length?'':'disabled'}>${icon('download')}تصدير Excel (.xlsx)</button><button class="btn primary" data-action="print-report" ${results.length?'':'disabled'}>${icon('print')}طباعة التقرير</button>`)+
 (results.some(r=>r.id===lastSavedResultId)?`<div class="saved-notice" role="status">${icon('check')}<div><b>تم حفظ النتيجة بنجاح</b><span>الدرجة مدرجة الآن في تحليل هذا الاختبار.</span></div><button class="btn small" data-action="scan-exam" data-id="${esc(q.id)}">تصحيح ورقة أخرى</button></div>`:'')+
 `<div class="filters"><select id="report-quiz" aria-label="الاختبار المراد تحليله">${quizOptions(reportQuiz)}</select><span class="muted" style="font-size:11px">تُحسب النسب من الأوراق المعتمدة فقط.</span></div>`+
 (!analysis||!results.length?`<section class="panel">${empty('النتائج تبدأ بورقة معتمدة','اختر اختبارًا وصحّح أوراقه. ستظهر هنا الدرجات وتحليلات الأسئلة والمهارات.',`<button class="btn primary" data-action="scan-exam" data-id="${q?esc(q.id):''}">${icon('scan')}ابدأ التصحيح</button>`)}</section>`:
 stats([['scan','عدد الأوراق',ar(results.length)],['chart','متوسط النسبة',pct(analysis.mean)],['target','أعلى نتيجة',pct(Math.max(...analysis.rows.map(r=>r.percent)))],['exam','أقل نتيجة',pct(Math.min(...analysis.rows.map(r=>r.percent)))]])+`<div class="grid-two"><section class="panel"><div class="panel-head"><div><h2>تحليل الأسئلة</h2><p>نسبة الإجابات الصحيحة لكل سؤال</p></div><span class="badge gold">ذهبي: أقل من ٧٥٪</span></div><div class="question-bars">${analysis.items.map(item=>`<div class="column" title="السؤال ${ar(item.number)}: ${pct(item.percent)}"><span>${fmt(item.percent)}</span><i class="${item.percent<75?'weak':''}" style="height:${Math.max(2,item.percent)}%"></i><b>${ar(item.number)}</b></div>`).join('')}</div></section><section class="panel"><div class="panel-head"><div><h2>مؤشرات المهارات</h2><p>مرجّحة بدرجات الأسئلة المرتبطة بالمهارة</p></div>${icon('target')}</div>${analysis.skills.map(s=>`<div class="bar-row"><div class="bar-label"><span>${esc(s.name)}</span><b>${pct(s.percent)}</b></div><div class="bar-track"><div class="bar-fill ${s.percent<75?'weak':''}" style="width:${s.percent}%"></div></div></div>`).join('')}</section></div>`+
 `<section class="panel"><div class="panel-head"><h2>أولوية التدريب</h2><span class="badge">مقترح مبني على النتائج</span></div>${analysis.skills.filter(s=>s.name!=='غير مصنّف'&&s.percent<75).sort((a,b)=>a.percent-b.percent).map(s=>`<div class="report-line"><div><b>${esc(s.name)}</b><p class="muted" style="font-size:11px">ابدأ بمثال محلول، ثم تدريب قصير، وأعد قياس المهارة.</p></div><span class="badge gold">${pct(s.percent)} إتقان</span></div>`).join('')||'<p class="muted" style="font-size:12px">لا توجد مهارة مصنّفة أقل من ٧٥٪ في هذه النتائج. راجع أداء كل طالب/ـة لتحديد احتياجاته الفردية.</p>'}</section>`+
 `<section class="panel"><div class="panel-head"><h2>سجل الدرجات</h2><input id="result-search" style="max-width:230px" placeholder="بحث بالاسم أو الرمز" aria-label="البحث في النتائج" value="${esc(search)}"></div><div class="table-wrap" id="results-table">${resultTable(analysis)}</div></section><section class="panel"><div class="panel-head"><h2>تفاصيل كل سؤال</h2><span class="muted" style="font-size:10px">الخانة الفارغة تُحسب غير صحيحة.</span></div><div class="table-wrap"><table><thead><tr><th>السؤال</th><th>المهارة</th><th>الإجابة الصحيحة</th><th>صحيح</th><th>فارغ</th><th>نسبة الصحة</th></tr></thead><tbody>${analysis.items.map((r,i)=>`<tr><td>${ar(i+1)}</td><td>${esc(r.skill)}</td><td>${letters[q.questions[i].answer]}</td><td>${ar(r.correct)}</td><td>${ar(r.blank)}</td><td><span class="badge ${r.percent<75?'gold':''}">${pct(r.percent)}</span></td></tr>`).join('')}</tbody></table></div></section>`);
}
function resultTable(a){const rows=a.rows.filter(r=>(r.name+' '+r.studentId).includes(search));return `<table><thead><tr><th>الاسم</th><th>الرمز</th><th>الدرجة</th><th>النسبة</th><th>التاريخ</th><th>المراجعة</th></tr></thead><tbody>${rows.map(r=>`<tr><td><b>${esc(r.name)}</b></td><td>${esc(r.studentId||'—')}</td><td>${fmt(r.score)} / ${fmt(r.total)}</td><td><span class="badge ${r.percent<75?'gold':''}">${pct(r.percent)}</span></td><td>${date(r.created)}</td><td><button class="btn small" data-action="result-detail" data-id="${esc(r.id)}">التفاصيل</button></td></tr>`).join('')||'<tr><td colspan="6">لا توجد نتيجة مطابقة للبحث.</td></tr>'}</tbody></table>`;}
function settingsPage(){return header('إعدادات مساحتك','احتفظ بعملك، وانقله معك أينما تحتاجه.')+`<div class="settings-grid"><div><section class="panel"><div class="panel-head"><h2>الحفظ والنقل</h2>${icon('shield')}</div><div class="setting-row"><div><h3>نسخة احتياطية كاملة</h3><p>الاختبارات، ومفاتيحها، والنتائج، وقائمة الطلبة.</p></div><button class="btn" data-action="backup">${icon('download')}تنزيل</button></div><div class="setting-row"><div><h3>استيراد نسخة محفوظة</h3><p>لن تُستبدل بياناتك الحالية إلا بعد تأكيدك.</p></div><button class="btn" data-action="import">${icon('upload')}استيراد</button></div>${loadError?'<div class="setting-row"><div><h3>تنزيل البيانات غير المقروءة</h3><p>احتفظ بالملف للمساعدة في استعادتها.</p></div><button class="btn" data-action="raw-backup">تنزيل نسخة الاستعادة</button></div>':''}<div class="setting-row"><div><h3>المظهر</h3><p>وضع فاتح أو ليلي يناسبك.</p></div><button class="btn" data-action="theme">${icon(db.theme==='dark'?'sun':'moon')}تغيير المظهر</button></div></section><section class="panel"><div class="panel-head"><h2>قائمة الطلبة</h2><span class="badge">اختيارية</span></div><p class="muted" style="font-size:11px;margin-bottom:14px">اكتب كل اسم في سطر. يمكنك إضافة الرمز بعد فاصلة، مثل: طالب تجريبي، ١٠١. تظهر الأسماء كاقتراحات عند التصحيح.</p><textarea id="roster-text" rows="6" placeholder="الاسم، الرمز">${esc(db.roster.map(r=>r.name+(r.code?'، '+r.code:'')).join('\n'))}</textarea><button class="btn primary" style="margin-top:12px" data-action="save-roster">${icon('check')}حفظ القائمة</button></section></div><div><section class="panel" style="background:var(--soft);border-color:transparent"><div class="panel-head"><h2>كيف تُحفظ بياناتك؟</h2>${icon('info')}</div><p style="font-size:12px;line-height:2.3">يعمل بصيرة داخل المتصفح. لا يرفع صور الأوراق أو النتائج إلى GitHub أو إلى أي خدمة تحليلية. الصور تُستخدم للقراءة فقط، ولا تدخل ضمن النسخة الاحتياطية.</p><p style="font-size:12px;line-height:2.3;margin-top:14px">لكل جهاز ومتصفح بياناته المستقلة. مسح بيانات الموقع أو استخدام التصفح الخاص قد يفقد العمل؛ نزّل نسخة احتياطية بانتظام. لا توجد مزامنة تلقائية بين الأجهزة.</p></section><section class="panel"><h3>مسح بيانات هذا المتصفح</h3><p class="muted" style="font-size:11px;margin:8px 0 15px">يحذف الاختبارات والنتائج وقائمة الطلبة من هذه المساحة. نزّل نسخة قبل المسح.</p><button class="btn danger" data-action="reset">${icon('trash')}مسح البيانات</button></section></div></div>`;}
function guidePage(){return header('دليلك إلى بصيرة','كل ما تحتاجه لبدء تصحيح واضح وتحليل مفيد.')+`<div class="guide-grid"><section class="guide-card"><span class="step-num">١</span><h3>أعدّ الاختبار واطبع النموذج</h3><ol><li>أنشئ اختبارًا وحدد عدد الأسئلة والخيارات.</li><li>أدخل الإجابة الصحيحة لكل سؤال، وأضف مهارته ودرجته إن رغبت.</li><li>افتح «النموذج» واطبعه على A4. اختر حجمًا فعليًا أو ملاءمة للصفحة دون قص، وأوقف رؤوس وتذييلات المتصفح.</li><li>وزّع ورقة الأسئلة منفصلة عن نموذج الإجابة، بنفس ترتيب الخيارات.</li></ol></section><section class="guide-card"><span class="step-num">٢</span><h3>التظليل والتصوير</h3><ul><li>ظلّل دائرة واحدة بالكامل لكل سؤال، بقلم داكن.</li><li>أظهر المربعات السوداء الأربعة في الصورة؛ فهي مرجع قراءة الورقة.</li><li>ضع الورقة بشكل رأسي ومستوي، وتجنب الظل والوهج والثني.</li><li>ارفع صورة أو عدة صور؛ تُراجع الصور وتُحفظ بالتتابع.</li><li>عند تعذّر الالتقاط التلقائي، حدد مراكز المربعات يدويًا بالترتيب الموضح.</li></ul></section><section class="guide-card"><span class="step-num">٣</span><h3>راجع ثم اعتمد</h3><ul><li>اختر الاختبار المطابق للعنوان وعدد الأسئلة على الورقة.</li><li>أدخل الاسم أو الرمز؛ لا يقرأ التطبيق الاسم المكتوب بخط اليد.</li><li>راجع كل الإجابات، وخاصة الفارغة، والمتعددة، والخفيفة.</li><li>اضغط الاختيار الصحيح كما يظهر على الورقة أو «فارغ»، ثم أكد المراجعة.</li><li>اضغط «اعتماد وحفظ النتيجة». راجع الاسم والاختبار والخانات المعلَّمة في نافذة التأكيد، ثم أكّد المراجعة والحفظ. تُحسب الخانة الفارغة غير صحيحة، ولا يُختار جواب من التظليل المزدوج تلقائيًا. بعد الحفظ يظهر التحليل مباشرة.</li></ul></section><section class="guide-card"><span class="step-num">٤</span><h3>اقرأ النتائج واحتفظ بها</h3><ul><li>يعرض التحليل درجات الطلبة، ونسب صحة الأسئلة، ومؤشرات المهارات.</li><li>نسبة المهارة = مجموع الدرجات المحققة في أسئلتها ÷ مجموع درجاتها الممكنة لجميع الأوراق المعتمدة.</li><li>اللون الذهبي يشير إلى نسبة أقل من ٧٥٪ كعتبة مساعدة للتدريب، وليس حكمًا رسميًا على الإتقان.</li><li>صدّر ملف Excel بصيغة .xlsx بثلاث أوراق: درجات الطلبة، وتحليل الأسئلة، وتحليل المهارات، أو اطبع تقريرًا/احفظه PDF من نافذة الطباعة.</li><li>خذ نسخة احتياطية لنقل بياناتك إلى جهاز آخر.</li></ul></section><section class="guide-card wide"><h3>نطاق القراءة</h3><p>بصيرة يقرأ نماذج التظليل التي ينشئها بنفسه؛ لا يدّعي التوافق مع كل نماذج ZipGrade أو نماذج الاختبارات الأخرى. يدعم الصور JPG وPNG وWEBP، وسؤالًا واحدًا بإجابة واحدة صحيحة، وخيارين إلى خمسة خيارات، وحتى ١٠٠ سؤال في الصفحة. لا يصحح الأسئلة المقالية أو خطوات الحل، ولا يقرأ أسماء الطلبة آليًا. لا يحدد الاختبار من الصورة؛ اختيار المفتاح المطابق مسؤولية المستخدم.</p><p style="margin-top:10px">القراءة البصرية تتأثر بالطباعة والتصوير والتظليل. اختُبرت آلية القراءة برمجيًا على صور مصطنعة؛ قارن نتائج مجموعة صغيرة من الأوراق المطبوعة بتصحيح يدوي قبل الاعتماد الفعلي. مراجعة المعلم تسبق اعتماد كل نتيجة.</p></section><section class="guide-card wide"><h3>استخدام عام… وبيانات مستقلة</h3><p>يمكن نشر ملفات التطبيق على GitHub Pages ومشاركة الرابط مع الجميع. لا يحتاج المستخدم إلى حساب، وتظل بياناته في متصفحه. عند استخدام جهاز مشترك، يستطيع من يستخدم المتصفح نفسه الوصول إلى البيانات المحفوظة؛ استخدم ملف متصفح مستقل أو صدّر عملك ثم امسحه. نشر التطبيق لا ينشر بيانات الاستخدام، لكن ملفات النسخ الاحتياطية تحتوي على النتائج والأسماء، فلا ترفعها إلى مستودع عام.</p></section></div>`;}

function sheetSVG(q,marks=null){const rows=O.layout(q.questions.length,q.options),cols=q.questions.length<=20?1:q.questions.length<=50?2:4,headRows=rows.filter((r,i)=>i===0||r.y===rows[0].y);return `<svg xmlns="http://www.w3.org/2000/svg" direction="ltr" width="800" height="1132" viewBox="0 0 800 1132"><rect width="800" height="1132" fill="white"/><g fill="#111" font-family="Tahoma,Arial,sans-serif"><text x="750" y="55" text-anchor="end" font-size="35" font-weight="bold">بصيرة</text><text x="50" y="48" font-size="14">A4 · ${ar(q.questions.length)} سؤال · ${ar(q.options)} خيارات</text><text x="400" y="90" text-anchor="middle" direction="rtl" font-size="22" font-weight="bold">${esc(q.title.slice(0,65))}</text><text x="750" y="123" text-anchor="start" font-size="17" direction="rtl">الاسم: .....................................................</text><text x="350" y="123" text-anchor="start" font-size="17" direction="rtl">الرمز: ..........................</text><text x="750" y="151" text-anchor="start" font-size="14" direction="rtl">${esc(q.className)} · ظلّل دائرة واحدة بالكامل لكل سؤال.</text><text x="400" y="204" text-anchor="middle" font-size="12" fill="#444" direction="rtl">لا تطوِ الورقة، وحافظ على وضوح المربعات السوداء الأربعة.</text>${O.MARKERS.map(p=>`<rect x="${p.x-9}" y="${p.y-9}" width="18" height="18" fill="#000"/>`).join('')}<rect x="65" y="187" width="12" height="6" fill="#000"/>${headRows.map(row=>row.bubbles.map((b,j)=>`<text x="${b.x}" y="${row.y-20}" font-size="14" text-anchor="middle">${letters[j]}</text>`).join('')).join('')}${rows.map(row=>`<text x="${row.x+3}" y="${row.y+5}" text-anchor="end" font-size="${cols===4?14:17}">${ar(row.i+1)}</text>${row.bubbles.map((b,j)=>`<circle cx="${b.x}" cy="${b.y}" r="${row.r}" fill="none" stroke="#111" stroke-width="1.2"/>${marks&&(Array.isArray(marks[row.i])?marks[row.i].includes(j):marks[row.i]===j)?`<circle cx="${b.x}" cy="${b.y}" r="${row.r*.78}" fill="#222"/>`:''}`).join('')}`).join('')}<text x="400" y="1089" text-anchor="middle" font-size="12" direction="rtl">إعداد: أ/ فاطمة هزازي — ملتقى التعليم التفاعلي</text><text x="400" y="1110" text-anchor="middle" font-size="10" fill="#555">BASIRAH · ${esc(q.id.slice(0,8))} · ${q.questions.length} × ${q.options}</text></g></svg>`;}
function showSheet(q){if(!q)return toast('اختر اختبارًا أولًا.');modal('نموذج الإجابة',`<p class="muted" style="font-size:12px">اطبع على A4، ولا تقص المربعات السوداء. وزّع الأسئلة في ورقة منفصلة. النموذج لا يحتوي على مفتاح الإجابة.</p><div class="preview-sheet">${sheetSVG(q)}</div>`,`<button class="btn primary" id="print-sheet">${icon('print')}طباعة / حفظ PDF</button><button class="btn" id="download-sheet">${icon('download')}تنزيل النموذج SVG</button>`);$('#print-sheet').onclick=()=>printContent(`<div class="sheet-print">${sheetSVG(q)}</div>`);$('#download-sheet').onclick=()=>download('basirah-answer-sheet.svg',sheetSVG(q),'image/svg+xml');}
function printContent(html){$('#print-area').innerHTML=html;document.fonts.ready.then(()=>{window.print();});}
function cleanScan(qid=''){scan={quizId:qid,canvas:null,corners:null,manual:false,points:[],answers:null,readings:null,reviewed:[],confirmed:false,demo:false,name:'',studentId:'',queue:[],queueTotal:0};}
function bindScanner(){if(scan.canvas)drawScan();const zone=$('#dropzone');if(zone){zone.ondragover=e=>{e.preventDefault();zone.classList.add('drag');};zone.ondragleave=()=>zone.classList.remove('drag');zone.ondrop=e=>{e.preventDefault();zone.classList.remove('drag');loadFiles([...e.dataTransfer.files]);};}const canvas=$('#scan-canvas');if(canvas)canvas.onclick=e=>{if(!scan.manual)return;const rect=canvas.getBoundingClientRect(),x=(e.clientX-rect.left)*canvas.width/rect.width,y=(e.clientY-rect.top)*canvas.height/rect.height;scan.points.push({x,y});if(scan.points.length===4){if(!O.validCorners(scan.points,scan.canvas.width,scan.canvas.height)){scan.points=[];toast('ترتيب المربعات غير صحيح. ابدأ من أعلى اليسار باتجاه عقارب الساعة.');drawScan();return;}scan.corners=scan.points.slice();scan.manual=false;analyzeScan();render();}else{drawScan();$('#alignment-message').innerHTML=notice(`الخطوة ${ar(scan.points.length+1)} من ٤: حدد مركز المربع ${['أعلى اليسار','أعلى اليمين','أسفل اليمين','أسفل اليسار'][scan.points.length]}.`);}};}
function drawScan(){const c=$('#scan-canvas');if(!c||!scan.canvas)return;c.width=scan.canvas.width;c.height=scan.canvas.height;const ctx=c.getContext('2d');ctx.drawImage(scan.canvas,0,0);const p=scan.manual?scan.points:scan.corners||[];ctx.lineWidth=Math.max(2,c.width/320);ctx.strokeStyle='#00ad86';ctx.fillStyle='#006c67';p.forEach((p,i)=>{const r=c.width/70;ctx.beginPath();ctx.arc(p.x,p.y,r,0,Math.PI*2);ctx.stroke();ctx.beginPath();ctx.moveTo(p.x-r*1.5,p.y);ctx.lineTo(p.x+r*1.5,p.y);ctx.moveTo(p.x,p.y-r*1.5);ctx.lineTo(p.x,p.y+r*1.5);ctx.stroke();ctx.font=`bold ${c.width/45}px Arial`;ctx.fillText(ar(i+1),p.x+r,p.y-r);});if(p.length===4){ctx.setLineDash([10,8]);ctx.beginPath();ctx.moveTo(p[0].x,p[0].y);p.slice(1).forEach(p=>ctx.lineTo(p.x,p.y));ctx.closePath();ctx.stroke();ctx.setLineDash([]);}}
async function loadFiles(files){if(!quizById(scan.quizId))return toast('اختر اختبارًا قبل رفع الصور.');const valid=files.filter(f=>/^image\/(jpeg|png|webp)$/.test(f.type)&&f.size<=20*1024*1024);if(valid.length!==files.length)toast('تُقبل صور JPG وPNG وWEBP بحجم لا يزيد على ٢٠ ميجابايت.');if(!valid.length)return;if(valid.length>100)return toast('اختر حتى ١٠٠ صورة في الدفعة الواحدة.');scan.demo=false;scan.queue=valid.slice(1);scan.queueTotal=valid.length;await loadFile(valid[0]);}
async function loadFile(file){try{toast('جارٍ قراءة الورقة على جهازك…');const url=URL.createObjectURL(file);try{const image=await imageFrom(url);if(image.width*image.height>60e6)throw Error('أبعاد الصورة كبيرة جدًا. صغّرها ثم أعد رفعها.');setScanImage(image);}finally{URL.revokeObjectURL(url);}render();}catch(e){toast(e.message||'تعذّر فتح الصورة.');}}
function imageFrom(url){return new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>resolve(im);im.onerror=()=>reject(Error('تعذّر قراءة الصورة. جرّب JPG أو PNG.'));im.src=url;});}
function setScanImage(image){const ratio=Math.min(1,1800/Math.max(image.width,image.height)),c=document.createElement('canvas');c.width=Math.round(image.width*ratio);c.height=Math.round(image.height*ratio);c.getContext('2d',{willReadFrequently:true}).drawImage(image,0,0,c.width,c.height);scan.canvas=c;scan.error='';scan.answers=null;scan.readings=null;scan.manual=false;scan.points=[];scan.name=scan.demo?'ورقة تدريبية':'';scan.studentId='';scan.confirmed=false;scan.corners=O.detectMarkers(c.getContext('2d').getImageData(0,0,c.width,c.height));if(scan.corners)analyzeScan();}
function analyzeScan(){scan.error='';try{const q=quizById(scan.quizId);if(!q)return;const c=scan.canvas;scan.readings=O.analyze(c.getContext('2d').getImageData(0,0,c.width,c.height),q.questions.length,q.options,scan.corners);scan.answers=scan.readings.map(r=>r.answer);scan.reviewed=scan.answers.map(()=>false);scan.confirmed=false;}catch(e){scan.answers=null;scan.readings=null;scan.error=e.message;toast(e.message);}}
async function demo(){cleanScan('demo');scan.demo=true;const answers=sample.questions.map(q=>q.answer);answers[1]=0;answers[3]=null;answers[6]=[1,2];const url=URL.createObjectURL(new Blob([sheetSVG(sample,answers)],{type:'image/svg+xml'}));try{const im=await imageFrom(url);setScanImage(im);go('scan');if(route==='scan')render();toast('ورقة تجربة: إجابة خاطئة، وخانة فارغة، وتظليل مزدوج.');}finally{URL.revokeObjectURL(url);}}
async function camera(){if(!navigator.mediaDevices?.getUserMedia)return toast('الكاميرا تحتاج إلى HTTPS ومتصفح يدعمها. يمكنك رفع صورة من جهازك.');modal('التقاط ورقة الإجابة','<p class="muted" style="font-size:12px;margin-bottom:12px">أظهر الصفحة رأسيًا كاملة مع المربعات الأربعة.</p><video id="camera-video" autoplay playsinline muted></video>','<button class="btn primary" id="capture-photo" disabled>التقاط الصورة</button><button class="btn" data-action="close-modal">إلغاء</button>');try{cameraStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'},width:{ideal:1920},height:{ideal:2560}},audio:false});if(!$('#modal').open){stopCamera();return;}const video=$('#camera-video');video.srcObject=cameraStream;await video.play();$('#capture-photo').disabled=false;$('#capture-photo').onclick=()=>{const c=document.createElement('canvas');c.width=video.videoWidth;c.height=video.videoHeight;c.getContext('2d').drawImage(video,0,0);closeModal();scan.demo=false;scan.queue=[];setScanImage(c);render();};}catch(e){stopCamera();closeModal();toast('لم نستطع فتح الكاميرا. اسمح بالوصول إليها، أو ارفع صورة محفوظة.');}}
function saveFeedback(message,focus){const box=$('#save-feedback');if(box){box.textContent=message;box.hidden=false;}toast(message);if(focus){focus.setAttribute('aria-invalid','true');focus.focus();focus.scrollIntoView({block:'center'});}}
async function saveResult(){
 const q=quizById(scan.quizId);
 if(!q||!scan.answers)return saveFeedback('اختر الاختبار وارفع صورة الورقة أولًا.');
 if(scan.demo||q.id==='demo'||!db.quizzes.some(item=>item.id===q.id))return saveFeedback('هذه تجربة جاهزة. استورد اختبارًا أو أنشئ اختبارك لحفظ النتائج.');
 scan.name=$('#scan-name')?.value??scan.name;scan.studentId=$('#scan-student')?.value??scan.studentId;
 if(!scan.name.trim())return saveFeedback('اكتب اسم الطالب/ـة أو رمزًا مستعارًا في خانة الاسم، ثم اضغط الحفظ.',$('#scan-name'));
 const result={id:id(),quizId:q.id,name:scan.name.trim(),studentId:scan.studentId.trim(),answers:[...scan.answers],created:new Date().toISOString(),reviewed:true};
 const pending=scan.readings.map((r,i)=>({reading:r,index:i})).filter(item=>item.reading.status!=='clear'&&!scan.reviewed[item.index]);
 const g=O.grade(q,result.answers),existing=db.results.find(r=>r.quizId===q.id&&(result.studentId?r.studentId===result.studentId:r.name===result.name&&!r.studentId));
 const labels={blank:'بلا إجابة',multiple:'تظليل متعدد',uncertain:'تظليل غير واضح'};
 modal('تأكيد حفظ النتيجة',`<div class="save-summary"><h3>${esc(q.title)}</h3><p>اسم الطالب/ـة: <b>${esc(result.name)}</b></p>${result.studentId?`<p>الرمز: ${esc(result.studentId)}</p>`:''}<div class="score-preview"><strong>${fmt(g.score)} من ${fmt(g.total)}</strong><span>${pct(g.percent)}</span></div></div>${pending.length?`<div class="save-flags"><h3>${ar(pending.length)} إجابة تحتاج إلى قرارك</h3><p>راجع هذه الخانات في صورة الورقة. عند التأكيد ستُعتمد الاختيارات الموضحة أدناه دون تخمين.</p><ul>${pending.map(({reading,index})=>`<li><b>السؤال ${ar(index+1)}: ${labels[reading.status]||'بحاجة إلى مراجعة'}</b><span>${result.answers[index]===null?'سيُعتمد بلا إجابة ويُحسب دون درجة.':'سيُعتمد الاختيار '+letters[result.answers[index]]+' ويُصحح وفق مفتاح الاختبار.'}</span></li>`).join('')}</ul><p>إذا أردت تعديل اختيار، اضغط «العودة للمراجعة».</p></div>`:''}${existing?notice('لهذا الاسم أو الرمز نتيجة محفوظة في الاختبار نفسه. التأكيد سيستبدل النتيجة السابقة بهذه النتيجة.'):''}<label class="checkbox save-confirm"><input type="checkbox" id="save-final-confirm"><span>راجعت الورقة والإجابات، وأؤكد صحة الاسم ومطابقة الاختبار المختار.</span></label><div id="result-save-error" class="error-text" role="alert" hidden></div>`,`<button class="btn primary" id="confirm-save-result">${icon('check')}${existing?'تأكيد استبدال النتيجة':'تأكيد وحفظ النتيجة'}</button><button class="btn" data-action="close-modal">العودة للمراجعة</button>`);
 let committing=false;
 $('#confirm-save-result').onclick=async()=>{
  if(committing)return;
  const error=$('#result-save-error'),check=$('#save-final-confirm'),button=$('#confirm-save-result');
  if(!check.checked){error.textContent='فعّل مربع تأكيد مراجعة الورقة أعلاه لإتمام الحفظ.';error.hidden=false;check.focus();return;}
  committing=true;button.disabled=true;button.textContent='جارٍ الحفظ…';error.hidden=true;
  const old=[...db.results];
  if(existing)db.results=db.results.filter(r=>r.id!==existing.id);
  db.results.push(result);
  try{save();}catch(e){db.results=old;committing=false;button.disabled=false;button.textContent='إعادة محاولة الحفظ';error.textContent=e.message||'تعذّر حفظ النتيجة. ما زالت الورقة متاحة للمراجعة.';error.hidden=false;return;}
  closeModal();lastSavedResultId=result.id;reportQuiz=q.id;search='';
  const next=scan.queue.shift();
  if(next){await loadFile(next);toast('تم حفظ النتيجة. راجع الورقة التالية وأدخل اسمها.');}
  else{cleanScan(q.id);go('results');toast('تم حفظ النتيجة بنجاح وعرض تحليلها.');}
 };
}

function exportExcel(){
 const q=quizById(reportQuiz);if(!q)return;
 const a=O.aggregate(q,db.results.filter(r=>r.quizId===q.id));if(!a.rows.length)return;
 try{
  if(!globalThis.BasirahExcel)throw Error('لم يكتمل تحميل التصدير. حدّث الصفحة ثم حاول مرة أخرى.');
  download('basirah-results.xlsx',BasirahExcel.build(q,a),BasirahExcel.MIME);
  toast('جُهّز ملف Excel (.xlsx) بثلاث أوراق: الدرجات والأسئلة والمهارات.');
 }catch(error){toast(error.message||'تعذّر إنشاء ملف Excel. حاول مرة أخرى.');}
}
function printReport(){const q=quizById(reportQuiz);if(!q)return;const a=O.aggregate(q,db.results.filter(r=>r.quizId===q.id));printContent(`<section class="report-print" dir="rtl"><div class="print-brand"><h1>بصيرة · تقرير نتائج الاختبار</h1><p>${esc(q.title)} · ${esc(q.className)} · ${date(new Date())}</p></div><div class="report-summary"><span>الأوراق: ${ar(a.rows.length)}</span><span>المتوسط: ${pct(a.mean)}</span></div><h2>درجات الطلبة</h2><table><thead><tr><th>الاسم</th><th>الرمز</th><th>الدرجة</th><th>النسبة</th></tr></thead><tbody>${a.rows.map(r=>`<tr><td>${esc(r.name)}</td><td>${esc(r.studentId)}</td><td>${fmt(r.score)} / ${fmt(r.total)}</td><td>${pct(r.percent)}</td></tr>`).join('')}</tbody></table><h2>تحليل المهارات</h2><table><thead><tr><th>المهارة</th><th>الدرجات المحققة</th><th>الدرجات الممكنة</th><th>النسبة</th></tr></thead><tbody>${a.skills.map(s=>`<tr><td>${esc(s.name)}</td><td>${fmt(s.earned)}</td><td>${fmt(s.total)}</td><td>${pct(s.percent)}</td></tr>`).join('')}</tbody></table><h2>تحليل الأسئلة</h2><table><thead><tr><th>السؤال</th><th>المهارة</th><th>صحيح</th><th>فارغ</th><th>نسبة الصحة</th></tr></thead><tbody>${a.items.map(s=>`<tr><td>${ar(s.number)}</td><td>${esc(s.skill)}</td><td>${ar(s.correct)}</td><td>${ar(s.blank)}</td><td>${pct(s.percent)}</td></tr>`).join('')}</tbody></table><p>نسبة المهارة مرجّحة بدرجات الأسئلة. الخانات الفارغة ضمن الدرجات الممكنة ولا تُعد إجابات صحيحة.</p><p class="print-foot">إعداد: أ/ فاطمة هزازي — ملتقى معلمي ومعلمات الرياضيات — ملتقى التعليم التفاعلي</p></section>`);}
function detail(resultId){const r=db.results.find(r=>r.id===resultId),q=r&&quizById(r.quizId);if(!q)return;const g=O.grade(q,r.answers);modal(r.name,`<p class="muted">${esc(q.title)} · ${date(r.created)}</p><div class="score-preview"><strong>${fmt(g.score)} من ${fmt(g.total)}</strong><span>${pct(g.percent)}</span></div><div class="details-answers">${r.answers.map((v,i)=>`<div class="${v===q.questions[i].answer?'':'wrong'}"><b>س ${ar(i+1)}</b><br>الإجابة: ${v===null?'فارغ':letters[v]}<br>الصحيح: ${letters[q.questions[i].answer]}</div>`).join('')}</div>`,`<button class="btn danger" id="delete-result">${icon('trash')}حذف النتيجة</button><button class="btn" data-action="close-modal">إغلاق</button>`);$('#delete-result').onclick=()=>confirmAction('حذف النتيجة',`سيُحذف سجل ${r.name} من هذا الاختبار.`,()=>{const old=db.results;db.results=db.results.filter(x=>x.id!==r.id);try{save();}catch(e){db.results=old;throw e;}render();toast('حُذفت النتيجة.');},'حذف');}
function examMenu(q){modal('خيارات الاختبار',`<h3>${esc(q.title)}</h3><p class="muted" style="font-size:12px;margin-top:6px">نسخة الاختبار القابلة للمشاركة تتضمن مفتاح الإجابة والمهارات، ولا تتضمن بيانات الطلبة.</p>`,`<button class="btn" data-action="edit-exam" data-id="${esc(q.id)}">${icon('edit')}تعديل</button><button class="btn" data-action="copy-exam" data-id="${esc(q.id)}">${icon('copy')}نسخ</button><button class="btn" data-action="export-exam" data-id="${esc(q.id)}">${icon('download')}تصدير الاختبار</button><button class="btn danger" data-action="delete-exam" data-id="${esc(q.id)}">${icon('trash')}حذف</button>`);}
function backup(){if(loadError)return toast('استخدم تنزيل نسخة الاستعادة في الإعدادات.');download('basirah-backup-'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify({type:'basirah-backup',exported:new Date().toISOString(),...db},null,2),'application/json');toast('نُزّلت النسخة الاحتياطية. احتفظ بها في مكان مناسب.');}
function validateQuiz(q){if(!q||typeof q.id!=='string'||q.id.length>100||typeof q.title!=='string'||!q.title.trim()||q.title.length>100||typeof q.className!=='string'||q.className.length>60||!Number.isInteger(q.options)||q.options<2||q.options>5||!Array.isArray(q.questions)||q.questions.length<1||q.questions.length>100||!Number.isFinite(Date.parse(q.created)))throw Error('بيانات الاختبار غير صالحة.');return {id:q.id,title:q.title,className:q.className,options:q.options,created:q.created,questions:q.questions.map(x=>{if(!x||!Number.isInteger(x.answer)||x.answer<0||x.answer>=q.options||typeof x.skill!=='string'||x.skill.length>60||!Number.isFinite(x.weight)||x.weight<.5||x.weight>100)throw Error('مفتاح الإجابة غير صالح.');return {answer:x.answer,skill:x.skill,weight:x.weight};})};}
function validateDB(raw){if(!raw||raw.version!==1||!Array.isArray(raw.quizzes)||raw.quizzes.length>500||!Array.isArray(raw.results)||raw.results.length>20000||!Array.isArray(raw.roster)||raw.roster.length>3000)throw Error('صيغة النسخة غير متوافقة.');const quizzes=raw.quizzes.map(validateQuiz);if(new Set(quizzes.map(q=>q.id)).size!==quizzes.length)throw Error('معرّفات اختبارات مكررة.');const results=raw.results.map(r=>{const q=quizzes.find(q=>q.id===r.quizId);if(!q||typeof r.id!=='string'||r.id.length>100||typeof r.name!=='string'||!r.name.trim()||r.name.length>100||typeof r.studentId!=='string'||r.studentId.length>40||!Array.isArray(r.answers)||r.answers.length!==q.questions.length||r.answers.some(a=>a!==null&&(!Number.isInteger(a)||a<0||a>=q.options))||!Number.isFinite(Date.parse(r.created))||r.reviewed!==true)throw Error('سجل نتائج غير صالح.');return {id:r.id,quizId:q.id,name:r.name,studentId:r.studentId,answers:[...r.answers],created:r.created,reviewed:true};});if(new Set(results.map(r=>r.id)).size!==results.length)throw Error('معرّفات نتائج مكررة.');const roster=raw.roster.map(r=>{if(!r||typeof r.name!=='string'||r.name.length>100||typeof r.code!=='string'||r.code.length>40)throw Error('قائمة الطلبة غير صالحة.');return {name:r.name,code:r.code};});return {version:1,quizzes,results,roster,theme:raw.theme==='dark'?'dark':'light'};}
async function importFile(file){if(!file)return;if(file.size>15*1024*1024)return toast('حجم النسخة أكبر من الحد المسموح، ١٥ ميجابايت.');try{const raw=JSON.parse(await file.text());if(raw.type==='basirah-quiz'){const q=validateQuiz(raw.quiz);q.id=id();q.created=new Date().toISOString();confirmAction('استيراد اختبار',`إضافة «${q.title}» بمفتاحه ومهاراته إلى اختباراتك؟`,()=>{db.quizzes.push(q);try{save();}catch(e){db.quizzes.pop();throw e;}go('exams');render();toast('أُضيف الاختبار.');},'إضافة الاختبار');}else{const next=validateDB(raw);confirmAction('استعادة نسخة احتياطية',`تحتوي النسخة على ${ar(next.quizzes.length)} اختبار و${ar(next.results.length)} نتيجة. ستستبدل جميع البيانات الحالية في هذا المتصفح. نزّل نسخة من عملك الحالي قبل المتابعة.`,()=>{const old=db;db=next;loadError=false;try{save();}catch(e){db=old;throw e;}cleanScan();draft=null;reportQuiz='';go('home');render();toast('استُعيدت النسخة.');},'استبدال البيانات');}}catch(e){toast('تعذّر الاستيراد: '+(e.message||'ملف غير صالح'));}}

document.addEventListener('click',async e=>{const n=e.target.closest('[data-nav]');if(n){go(n.dataset.nav);return;}const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const action=b.dataset.action,q=quizById(b.dataset.id);try{
 if(action==='new-exam')newDraft();
 else if(action==='close-modal')closeModal();
 else if(action==='demo')await demo();
 else if(action==='key'){const i=+b.dataset.q;draft.questions[i].answer=+b.dataset.a;b.closest('.key-choices').querySelectorAll('button').forEach(el=>{el.classList.toggle('on',el===b);el.setAttribute('aria-pressed',el===b?'true':'false');});$('#key-progress').textContent=ar(draft.questions.filter(q=>q.answer!==null).length)+' من '+ar(draft.questions.length)+' إجابة محددة';}
 else if(action==='save-exam'){captureDraft();if(!draft.title)return toast('أدخل عنوان الاختبار.');if(draft.questions.some(q=>q.answer===null))return toast('حدّد الإجابة الصحيحة لجميع الأسئلة.');const ready=validateQuiz(draft),old=db.quizzes.findIndex(q=>q.id===ready.id),previous=[...db.quizzes];if(old>=0)db.quizzes[old]=ready;else db.quizzes.push(ready);try{save();}catch(e){db.quizzes=previous;throw e;}draft=null;go('exams');toast('حُفظ الاختبار. النموذج جاهز للطباعة.');}
 else if(action==='sheet')showSheet(q);
 else if(action==='scan-exam'){if(q)cleanScan(q.id);go('scan');if(route==='scan')render();}
 else if(action==='report-exam'){reportQuiz=q.id;go('results');}
 else if(action==='exam-menu')examMenu(q);
 else if(action==='edit-exam'){if(db.results.some(r=>r.quizId===q.id))return toast('للحفاظ على سلامة النتائج، انسخ الاختبار ثم عدّل النسخة الجديدة.');closeModal();newDraft(q);}
 else if(action==='copy-exam'){const copy=JSON.parse(JSON.stringify(q));copy.id=id();copy.title=(copy.title+' · نسخة').slice(0,100);copy.created=new Date().toISOString();closeModal();newDraft(copy);}
 else if(action==='export-exam')download('basirah-quiz.json',JSON.stringify({type:'basirah-quiz',quiz:q},null,2),'application/json');
 else if(action==='delete-exam')confirmAction('حذف الاختبار',`سيُحذف «${q.title}» وجميع نتائجه من هذا المتصفح.`,()=>{const before=JSON.parse(JSON.stringify(db));db.quizzes=db.quizzes.filter(x=>x.id!==q.id);db.results=db.results.filter(x=>x.quizId!==q.id);try{save();}catch(e){db=before;throw e;}if(scan.quizId===q.id)cleanScan();render();toast('حُذف الاختبار ونتائجه.');},'حذف الاختبار');
 else if(action==='choose-images'){$('#file-input').value='';$('#file-input').click();}
 else if(action==='camera')await camera();
 else if(action==='manual-corners'){scan.error='';scan.manual=true;scan.points=[];scan.corners=null;scan.answers=null;scan.readings=null;scan.confirmed=false;render();}
 else if(action==='rotate'){const c=document.createElement('canvas');c.width=scan.canvas.height;c.height=scan.canvas.width;const ctx=c.getContext('2d');ctx.translate(c.width,0);ctx.rotate(Math.PI/2);ctx.drawImage(scan.canvas,0,0);setScanImage(c);render();}
 else if(action==='clear-scan'){cleanScan(scan.quizId==='demo'?'':scan.quizId);render();}
 else if(action==='review-answer'){const i=+b.dataset.q;scan.answers[i]=b.dataset.a==='blank'?null:+b.dataset.a;scan.reviewed[i]=true;scan.confirmed=false;updateReview();}
 else if(action==='confirm-answer'){scan.reviewed[+b.dataset.q]=true;scan.confirmed=false;updateReview();}
 else if(action==='save-result')await saveResult();
 else if(action==='export-excel')exportExcel();
 else if(action==='print-report')printReport();
 else if(action==='result-detail')detail(b.dataset.id);
 else if(action==='backup')backup();
 else if(action==='raw-backup')download('basirah-recovery.txt',localStorage.getItem(KEY)||'','text/plain');
 else if(action==='import'){$('#backup-input').value='';$('#backup-input').click();}
 else if(action==='save-roster'){const text=$('#roster-text').value.trim();if(text.length>400000)throw Error('القائمة طويلة جدًا.');const list=text?text.split(/\r?\n/).filter(x=>x.trim()).map(line=>{const p=line.split(/[,،\t]/);return {name:p[0].trim(),code:(p[1]||'').trim()};}):[];if(list.length>3000||list.some(r=>!r.name||r.name.length>100||r.code.length>40))throw Error('تحقق من طول الأسماء والرموز. الحد الأقصى ٣٠٠٠ اسم.');const old=db.roster;db.roster=list;try{save();}catch(e){db.roster=old;throw e;}toast('حُفظت قائمة الطلبة.');}
 else if(action==='reset')confirmAction('مسح جميع البيانات','سيُحذف كل عملك في هذا المتصفح. تأكد من تنزيل نسخة احتياطية قبل المتابعة.',()=>{localStorage.removeItem(KEY);db={version:1,quizzes:[],results:[],roster:[],theme:db.theme};loadError=false;cleanScan();draft=null;reportQuiz='';render();toast('مُسحت البيانات من هذا المتصفح.');},'مسح نهائي');
 else if(action==='theme')toggleTheme();
 }catch(error){toast(error.message||'تعذّر إكمال العملية.');}});
document.addEventListener('input',e=>{const el=e.target;if(el.id==='quiz-title'||el.id==='quiz-class')captureDraft();if(el.dataset.skill!==undefined)draft.questions[+el.dataset.skill].skill=el.value;if(el.dataset.weight!==undefined)draft.questions[+el.dataset.weight].weight=Number(el.value);if(el.id==='scan-name'){scan.name=el.value;scan.confirmed=false;const roster=db.roster.find(r=>r.name===el.value);if(roster){scan.studentId=roster.code;$('#scan-student').value=roster.code;}el.removeAttribute('aria-invalid');if($('#save-feedback'))$('#save-feedback').hidden=true;}if(el.id==='scan-student'){scan.studentId=el.value;scan.confirmed=false;el.removeAttribute('aria-invalid');if($('#save-feedback'))$('#save-feedback').hidden=true;}if(el.id==='result-search'){search=el.value;const q=quizById(reportQuiz);$('#results-table').innerHTML=resultTable(O.aggregate(q,db.results.filter(r=>r.quizId===q.id)));}});
document.addEventListener('change',e=>{const el=e.target;if(el.id==='quiz-count'){captureDraft();const n=Number(el.value);if(!Number.isInteger(n)||n<1||n>100){el.value=draft.questions.length;return toast('اختر عددًا صحيحًا من ١ إلى ١٠٠.');}draft.questions=Array.from({length:n},(_,i)=>draft.questions[i]||{answer:null,skill:'',weight:1});render();}if(el.id==='quiz-options'){captureDraft();draft.options=+el.value;draft.questions.forEach(q=>{if(q.answer>=draft.options)q.answer=null;});render();}if(el.id==='scan-quiz'){const qid=el.value;cleanScan(qid);render();}if(el.id==='report-quiz'){reportQuiz=el.value;search='';render();}if(el.id==='file-input')loadFiles([...el.files]);if(el.id==='backup-input')importFile(el.files[0]);});
function toggleTheme(){db.theme=db.theme==='dark'?'light':'dark';try{save();}catch(e){toast(e.message);}document.documentElement.dataset.theme=db.theme;$('#theme').innerHTML=icon(db.theme==='dark'?'sun':'moon');if(route==='settings')render();}
$('#theme').onclick=toggleTheme;$('#modal').addEventListener('close',stopCamera);$('#modal').addEventListener('cancel',stopCamera);window.addEventListener('hashchange',()=>{stopCamera();render();window.scrollTo(0,0);});window.addEventListener('pagehide',stopCamera);
window.addEventListener('beforeunload',e=>{if((scan.canvas&&!scan.demo)||draft){e.preventDefault();e.returnValue='';}});
render();
